const seen = new Set();
const rows = [];
for (const item of $input.all()) {
  const key = item.json.workflow_id;
  if (seen.has(key)) continue;
  seen.add(key);
  rows.push(item.json);
}

const settings = $('Watchdog Settings').first().json;
const sweepStart = new Date(settings.sweepStartedAt);

const tally = { HEALTHY: 0, EMPTY: 0, STALE: 0, DARK: 0, UNREADABLE: 0, NOT_CHECKED: 0 };
const blindSpots = [];
const faults = [];

for (const row of rows) {
  const checkedAt = row.last_checked_at ? new Date(row.last_checked_at) : null;
  const checkedThisSweep = checkedAt !== null && !isNaN(checkedAt.getTime()) && checkedAt >= sweepStart;
  const state = checkedThisSweep ? (String(row.last_state || '') || 'UNREADABLE') : 'NOT_CHECKED';
  const name = row.label || row.workflow_id || 'unnamed row';

  tally[state] = (tally[state] || 0) + 1;

  if (state === 'UNREADABLE' || state === 'NOT_CHECKED') {
    blindSpots.push(name + ' (' + state.toLowerCase().replace('_', ' ') + ')');
  } else if (state !== 'HEALTHY') {
    faults.push(name + ' (' + state.toLowerCase() + ')');
  }
}

const lines = [];
if (blindSpots.length) {
  lines.push(':mag: The watchdog could not check ' + blindSpots.length + ' of ' + rows.length + ' watched workflow(s) this sweep.');
  lines.push('Not checked: ' + blindSpots.join(', ') + '.');
  lines.push('A row named here was never given a verdict, so treat its state as unknown rather than healthy.');
  if (faults.length) lines.push('Separately, still unhealthy: ' + faults.join(', ') + '.');
} else {
  lines.push('Checked all ' + rows.length + ' watched workflow(s) this sweep.');
}

return [{
  json: {
    watched: rows.length,
    tally: tally,
    faults: faults,
    blindSpots: blindSpots,
    blindSpotDecision: blindSpots.length > 0 ? 'report' : 'none',
    text: lines.join('\n')
  }
}];

const input = $input.first().json;

let raw = input.data;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch (e) { raw = null; }
}

const runData = (raw && raw.resultData && raw.resultData.runData) || {};
const lastNode = (raw && raw.resultData && raw.resultData.lastNodeExecuted) || '';
const nodeNames = Object.keys(runData);

function countItems(runs) {
  let total = 0;
  for (const run of runs || []) {
    const branches = (run && run.data && run.data.main) || [];
    for (const branch of branches) {
      total += (branch || []).length;
    }
  }
  return total;
}

let producedByLastNode = 0;
let producedTotal = 0;
const perNode = {};

for (const name of nodeNames) {
  const count = countItems(runData[name]);
  perNode[name] = count;
  producedTotal += count;
  if (name === lastNode) producedByLastNode = count;
}

const readable = nodeNames.length > 0;

return [{
  json: {
    observed: readable,
    readable: readable,
    readError: readable ? '' : 'the execution returned no readable run data',
    executionId: String(input.id || ''),
    finishedAt: input.stoppedAt || input.startedAt || '',
    lastNodeExecuted: lastNode,
    producedItems: producedByLastNode,
    producedTotal: producedTotal,
    perNode: perNode
  }
}];

const observation = $input.first().json;
const row = $('Check Each Watched Workflow').first().json;
const settings = $('Watchdog Settings').first().json;

const now = new Date();

function toDate(value) {
  if (!value) return null;
  const parsed = new Date(value);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function minutesSince(value) {
  const parsed = toDate(value);
  return parsed === null ? null : Math.round((now.getTime() - parsed.getTime()) / 60000);
}

function num(value, fallback) {
  const parsed = Number(value);
  return isFinite(parsed) ? parsed : fallback;
}

const expectEvery = Math.max(1, num(row.expect_every_minutes, 1440));
const minItems = Math.max(0, num(row.min_items, 1));
const grace = Math.max(1, num(settings.graceMultiplier, 1.5));
const cooldown = Math.max(0, num(settings.alertCooldownMinutes, 240));
const escalateAfter = Math.max(1, num(settings.escalateAfterMisses, 3));

const staleAfter = expectEvery * grace;
const darkAfter = staleAfter * 3;

const ageMinutes = observation.observed ? minutesSince(observation.finishedAt) : null;
const produced = num(observation.producedItems, 0);
const producedTotal = num(observation.producedTotal, 0);

let state;
let headline;

if (observation.readable === false) {
  state = 'UNREADABLE';
  headline = 'the watchdog could not read this workflow: ' + (observation.readError || 'unknown reason');
} else if (!observation.observed) {
  state = 'DARK';
  headline = 'no successful run exists in the retained history';
} else if (ageMinutes === null || ageMinutes > darkAfter) {
  state = 'DARK';
  headline = 'the last success is far outside the expected window';
} else if (ageMinutes > staleAfter) {
  state = 'STALE';
  headline = 'nothing has succeeded inside the expected window';
} else if (produced < minItems) {
  state = 'EMPTY';
  headline = 'the run finished green and produced nothing';
} else {
  state = 'HEALTHY';
  headline = 'ran on time and produced data';
}

const previousState = String(row.last_state || '') || 'UNKNOWN';
const stateChanged = state !== previousState;
const misses = state === 'HEALTHY' ? 0 : num(row.consecutive_misses, 0) + 1;
const minutesSinceAlert = minutesSince(row.last_alert_at);
const cooldownOver = minutesSinceAlert === null || minutesSinceAlert >= cooldown;
const escalated = misses >= escalateAfter;
const shouldAlert = state !== 'HEALTHY' && (stateChanged || (escalated && cooldownOver));

const label = row.label || row.workflow_id || 'unnamed workflow';
const rawBase = String(settings.instanceUrl || '').replace(/\/+$/, '');
const base = /^https?:\/\//.test(rawBase) ? rawBase : '';
let link = '';
if (base && row.workflow_id) {
  link = base + '/workflow/' + row.workflow_id;
  if (observation.executionId) link += '/executions/' + observation.executionId;
}

const lines = [];
lines.push((escalated ? ':rotating_light: ' : ':warning: ') + state + ' | ' + label);
lines.push(headline.charAt(0).toUpperCase() + headline.slice(1) + '.');
lines.push('Expected: a successful run every ' + expectEvery + ' min returning at least ' + minItems + ' item(s).');
if (observation.observed) {
  lines.push('Observed: last success ' + (ageMinutes === null ? 'at an unreadable time' : ageMinutes + ' min ago') + ', final node "' + (observation.lastNodeExecuted || 'unknown') + '" returned ' + produced + ' item(s), ' + producedTotal + ' across the whole run.');
} else {
  lines.push('Observed: nothing to read.');
}
lines.push('This state has now held for ' + misses + ' consecutive check(s).');
if (link) lines.push(link);

return [{
  json: {
    workflow_id: row.workflow_id || '',
    label: label,
    expect_every_minutes: expectEvery,
    min_items: minItems,
    state: state,
    previousState: previousState,
    stateChanged: stateChanged,
    escalated: escalated,
    consecutive_misses: misses,
    ageMinutes: ageMinutes,
    producedItems: produced,
    producedTotal: producedTotal,
    executionId: observation.executionId || '',
    checkedAt: now.toISOString(),
    healthyAt: state === 'HEALTHY' ? now.toISOString() : (row.last_healthy_at || ''),
    alertAt: shouldAlert ? now.toISOString() : (row.last_alert_at || ''),
    alertDecision: shouldAlert ? 'alert' : 'quiet',
    alertText: lines.join('\n')
  }
}];
